INSERT INTO mcp_user_tool_selection (token_id, tool_name, tool_type, is_enabled)
SELECT #{tokenId}, #{toolName}, #{toolType}, #{enabled}
WHERE NOT EXISTS (
    SELECT 1 FROM mcp_user_tool_selection
    WHERE token_id = #{tokenId} AND tool_name = #{toolName} AND tool_type = #{toolType}
)
